import { styled, View } from '@tamagui/web';
import type { AriaAttributes, AriaRole } from 'react';

import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { customProperties } from '../../helpers/customProperties';
import { prependClassName } from '../../helpers/prependClassName';
import type { DivAttributes } from '../../types/ElementAttributes';

const getWidth = (percentage: number): string => `${Math.min(Math.max(0, percentage), 100).toFixed(1)}%`;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const progressBarFrame = {
	render: 'div',
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	overflow: 'hidden',
	width: '100%',
	height: '8px',
	borderRadius: 'var(--rcx-progress-bar-border-radius, 0.5rem)',
	backgroundColor: 'var(--rcx-progress-bar-color-background, var(--rcx-color-surface-neutral, #e4e7ea))',
} as const;

const progressBarFill = {
	render: 'div',
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	width: 'var(--rcx-progress-bar-percentage, 0%)',
	height: '8px',
	borderRadius: 'var(--rcx-progress-bar-border-radius, 0.5rem)',
} as const;

const progressBarTones = {
	'info': {
		backgroundColor: 'var(--rcx-color-status-font-on-info, #095ad2)',
	},
	'light-info': {
		backgroundColor: 'var(--rcx-color-status-background-info, #d1ebfe)',
	},
	'success': {
		backgroundColor: 'var(--rcx-color-status-font-on-success, #148660)',
	},
	'light-success': {
		backgroundColor: 'var(--rcx-color-status-background-success, #c0f6e4)',
	},
	'warning': {
		backgroundColor: 'var(--rcx-color-status-font-on-warning, #895f00)',
	},
	'light-warning': {
		backgroundColor: 'var(--rcx-color-status-background-warning, #ffecad)',
	},
	'danger': {
		backgroundColor: 'var(--rcx-color-status-font-on-danger, #9b1325)',
	},
	'light-danger': {
		backgroundColor: 'var(--rcx-color-status-background-danger, #ffc1c9)',
	},
} as const;

// end of generated

const ProgressBarFrame = styled(View, { ...progressBarFrame });

const FillFrame = styled(View, {
	...progressBarFill,
	variants: {
		tone: progressBarTones,
	},
});

export type ProgressBarProps = {
	percentage: number;
	variant?: 'info' | 'success' | 'warning' | 'danger';
	error?: string;
	animated?: boolean;
	light?: boolean;
	role?: AriaRole;
} & DivAttributes &
	Pick<AriaAttributes, 'aria-label' | 'aria-labelledby' | 'aria-valuenow' | 'aria-valuemin' | 'aria-valuemax' | 'aria-valuetext'>;

/**
 * The `ProgressBar` is used to inform the user the progress of an operation.
 */
function ProgressBar(props: ProgressBarProps) {
	const { percentage, variant = 'info', error, animated, light = false, className } = props;
	const tone = error ? 'danger' : variant;

	return (
		<ProgressBarFrame
			className={prependClassName(className, 'rcx-box rcx-box--full rcx-progress-bar')}
			render={
				<div
					{...ariaAndDataAttributes(props)}
					ref={props.ref}
					id={props.id}
					title={props.title ?? (error || undefined)}
					role={props.role}
				/>
			}
		>
			<FillFrame
				tone={light ? `light-${tone}` : tone}
				className={`rcx-box rcx-box--full rcx-progress-bar__fill${animated ? ' rcx-progress-bar__fill--animated' : ''}`}
				render={<div {...customProperties({ '--rcx-progress-bar-percentage': getWidth(percentage) })} />}
			/>
		</ProgressBarFrame>
	);
}

export default ProgressBar;
